versions.variantCss:
.wemd-author-card[data-variant="bytedance-author-card"] {
  background: linear-gradient(135deg, var(--wemd-bg-soft), var(--wemd-bg-muted));
  border-radius: var(--wemd-border-radius);
  padding: 24px 28px;
  margin: 16px 0;
  text-align: center;
}
.wemd-author-card[data-variant="bytedance-author-card"] .wemd-component-body {
  padding: 0;
}
.wemd-author-card[data-variant="bytedance-author-card"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-primary);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin: 0 0 8px 0;
}
.wemd-author-card[data-variant="bytedance-author-card"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-strong);
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 8px 0;
}
.wemd-author-card[data-variant="bytedance-author-card"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-text-soft);
  font-size: 14px;
  line-height: 1.7;
  margin: 0;
}
